    "w": 1056,
    "h": 816,
    "html": "<div style=\"width: 1056px; height: 816px; box-sizing: border-box; background: #16306E; color: #FFFFFF; font-family: 'Public Sans', sans-serif; display: flex\">\n<div style=\"flex: 1; padding: 56px 52px 48px; display: flex; flex-direction: column; gap: 22px\">\n<div style=\"background: #FFFEFB; border-radius: 14px; padding: 14px 18px; align-self: flex-start\"><div style=\"display: flex; align-items: center; gap: 18px\"><img src=\"assets/logo-hvlc.png\" alt=\"Heart Vascular &amp; Leg Center logo\" style=\"height: 44px; width: 101px; object-fit: contain; object-position: left center\"><span style=\"width: 1px; height: 35px; background: #E2DED4\"></span><img src=\"assets/logo-long-nodivision.png\" alt=\"Advanced Joint Pain &amp; Vascular Center logo\" style=\"height: 44px; width: 167px; object-fit: contain; object-position: left center\"></div></div>\n<div style=\"flex: 1\"></div>\n<p style=\"margin: 0; font-family: 'Montserrat', sans-serif; font-weight: 700; font-size: 17px; letter-spacing: 4px; text-transform: uppercase; color: #F2A7A3\">Exam room flip chart</p>\n<h1 style=\"margin: 0; font-family: 'Montserrat', sans-serif; font-weight: 800; font-size: 58px; line-height: 1.04\">Understanding Joint, Artery &amp; Vein Conditions</h1>\n<p style=\"margin: 0; font-size: 22px; line-height: 1.4; color: #D9E1F2\">Conditions we treat and the minimally invasive procedures that can help</p>\n<div style=\"width: 120px; height: 8px; background: #C8231E\"></div></div>\n<div style=\"width: 420px; background: #FFFFFF; display: flex; align-items: center; justify-content: center; padding: 30px\"><img src=\"assets/circulation.jpg\" alt=\"Illustration of the body’s arteries and veins\" style=\"width: 100%; height: 100%; object-fit: contain\"></div></div>"
